import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';

const root=path.resolve(import.meta.dirname,'..');
const out=path.join(root,'dist');
const tools=JSON.parse(fs.readFileSync(path.join(root,'data/tools.json'),'utf8'));
const categories=JSON.parse(fs.readFileSync(path.join(root,'data/categories.json'),'utf8'));
const apis=JSON.parse(fs.readFileSync(path.join(root,'data/apis.json'),'utf8'));
const professions=JSON.parse(fs.readFileSync(path.join(root,'data/professions.json'),'utf8'));
const jobSources=JSON.parse(fs.readFileSync(path.join(root,'data/job-sources.json'),'utf8'));
const learning=JSON.parse(fs.readFileSync(path.join(root,'data/learning.json'),'utf8'));
const youtubeCourses=JSON.parse(fs.readFileSync(path.join(root,'data/youtube-courses.json'),'utf8'));
const AUTH_URL=process.env.SUPABASE_URL||'';
const AUTH_PUBLISHABLE_KEY=process.env.SUPABASE_PUBLISHABLE_KEY||'';
const PRIVACY_CONTACT_EMAIL=process.env.PRIVACY_CONTACT_EMAIL||'';
const AUTH_ENABLED=Boolean(AUTH_URL && AUTH_PUBLISHABLE_KEY && PRIVACY_CONTACT_EMAIL);
if(AUTH_ENABLED && (!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(AUTH_URL)||!/^sb_publishable_[A-Za-z0-9_-]+$/.test(AUTH_PUBLISHABLE_KEY)||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(PRIVACY_CONTACT_EMAIL))) throw Error('Invalid public authentication settings');
const affiliateConfig=JSON.parse(fs.readFileSync(path.join(root,'data/affiliates.json'),'utf8'));
const affiliates=affiliateConfig.links||{};
const SITE=(process.env.SITE_URL||'https://free-ai-taskbook.pages.dev').replace(/\/$/,'');
const REPO=(process.env.GITHUB_REPO_URL||'').replace(/\/$/,'');
if(REPO && !/^https:\/\/github\.com\/[a-zA-Z0-9_.-]+\/[a-zA-Z0-9_.-]+$/.test(REPO)) throw Error('GITHUB_REPO_URL must be a GitHub repository URL');
if(!/^https:\/\/[^\s/]+$/.test(SITE)) throw Error('SITE_URL must be HTTPS and contain no path');
const TODAY=new Date().toISOString().slice(0,10);
const accessLabels={'free':'Fully free','free-tier':'Free plan','free-credits':'Limited free credits','local-open-source':'Local / open source','free-software':'Free software'};
const icon={arrow:'↗',spark:'✦',diamond:'◆'};
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const canon=(p='/')=>`${SITE}${p}`;
const catMap=Object.fromEntries(categories.map(c=>[c.slug,c]));
const slugs=new Set();
for(const t of tools){
 if(!/^https:\/\//.test(t.url)||!/^https:\/\//.test(t.pricingUrl))throw Error(`Expected HTTPS links: ${t.name}`);
 if(slugs.has(t.slug)||!catMap[t.category]||!accessLabels[t.access])throw Error(`Invalid tool ${t.name}`);
 slugs.add(t.slug);
}
for(const [slug,url] of Object.entries(affiliates)){
 if(!slugs.has(slug)||!/^https:\/\//.test(url))throw Error(`Invalid affiliate entry: ${slug}`);
}
fs.rmSync(out,{recursive:true,force:true});fs.mkdirSync(out,{recursive:true});
function save(p,html){const full=path.join(out,p.replace(/^\//,''));fs.mkdirSync(path.dirname(full),{recursive:true});fs.writeFileSync(full,html,'utf8')}
const jsonld=obj=>`<script type="application/ld+json">${JSON.stringify(obj).replace(/</g,'\\u003c')}</script>`;
const brand=`<span class="mark" aria-hidden="true"><span>✳</span></span><span class="brand-label">freeai<span class="brand-highlight">taskbook</span><span class="brand-dot">.</span></span>`;
const nav=`<header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="FreeAITaskbook home">${brand}</a><nav class="main-nav" aria-label="Primary navigation"><a href="/search/">Search everything</a><a href="/#explore">Explore tools</a><a href="/categories/">Categories</a><a href="/guides/">Guides</a><a href="/professions/">Professions</a><a href="/jobs/">Jobs</a><a href="/learn/">Learn</a><a href="/apis/">APIs</a><a href="/account/">Account</a></nav><a class="header-cta" href="/submit/">+ Submit a tool <span aria-hidden="true">↗</span></a><button class="mobile-menu" aria-label="Open navigation" aria-expanded="false" type="button">☰</button></div></header>`;
const footer=`<footer class="site-footer"><div class="wrap"><div class="footer-top"><div><a class="brand" href="/">${brand}</a><p>Free-first AI discovery, with clearer limits and real-world use cases.<br/>Built openly for curious people everywhere.</p></div><div class="footer-links"><div><strong>Discover</strong><a href="/">All tools</a><a href="/categories/">Categories</a><a href="/guides/">Guides</a><a href="/apis/">API directory</a><a href="/professions/">Professional toolkits</a><a href="/jobs/">Job sources</a><a href="/learn/">Free learning</a></div><div><strong>Participate</strong><a href="/submit/">Submit a tool</a><a href="/account/">Account</a><a href="/about/">Our approach</a><a href="${attr(REPO||'https://github.com/new')}" rel="noopener noreferrer" target="_blank">GitHub</a></div><div><strong>Legal</strong><a href="/disclosure/">Affiliate disclosure</a><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getUTCFullYear()} FreeAITaskbook · Community-first and independently curated.</span><span>Made for the curious. No paywall.</span></div></div></footer>`;
function page({title,description,pathname='/',content,ld,keywords='',noindex=false}){
 const fullTitle=title==='FreeAITaskbook'?'Free AI Tools for Every Task | FreeAITaskbook':`${title} | FreeAITaskbook`;
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0c1321"><title>${esc(fullTitle)}</title><meta name="description" content="${attr(description)}">${keywords?`<meta name="keywords" content="${attr(keywords)}">`:''}<link rel="canonical" href="${attr(canon(pathname))}"><meta name="robots" content="${noindex?'noindex,follow':'index,follow,max-image-preview:large'}"><meta property="og:type" content="website"><meta property="og:site_name" content="FreeAITaskbook"><meta property="og:title" content="${attr(fullTitle)}"><meta property="og:description" content="${attr(description)}"><meta property="og:url" content="${attr(canon(pathname))}"><meta property="og:image" content="${attr(canon('/og.png'))}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/styles.css"><script src="/assets/app.js" defer></script>${ld?jsonld(ld):''}</head><body>${nav}<main id="main">${content}</main>${footer}</body></html>`;
}
const breadcrumb=(links)=>`<nav class="breadcrumbs" aria-label="Breadcrumb">${links.map((x,i)=>i===links.length-1?`<span aria-current="page">${esc(x.name)}</span>`:`<a href="${attr(x.url)}">${esc(x.name)}</a><span aria-hidden="true">/</span>`).join('')}</nav>`;
function tag(t){return `<span class="access access-${attr(t.access)}"><i class="status-dot"></i>${esc(accessLabels[t.access])}</span>`}
function card(t){const c=catMap[t.category];return `<article class="tool-card" data-tool data-title="${attr(t.name.toLowerCase())}" data-search="${attr([t.name,t.summary,t.description,c.name,...t.tasks].join(' ').toLowerCase())}" data-category="${attr(t.category)}" data-access="${attr(t.access)}" data-slug="${attr(t.slug)}"><div class="card-upper"><span class="tool-monogram" aria-hidden="true">${esc(t.name.slice(0,2).toUpperCase())}</span><button type="button" class="bookmark" data-favorite="${attr(t.slug)}" aria-label="Save ${attr(t.name)}" aria-pressed="false" title="Save tool">☆</button></div><div class="card-tagline"><span>${esc(c.name)}</span><span class="tiny-star" aria-hidden="true">✳</span></div><h3><a href="/tools/${attr(t.slug)}/">${esc(t.name)} <span aria-hidden="true" class="card-arrow">↗</span></a></h3><p>${esc(t.summary)}</p><div class="card-bottom">${tag(t)}<a class="card-details" href="/tools/${attr(t.slug)}/">Details <span aria-hidden="true">→</span></a></div></article>`}
const sectionHead=(kicker,title,desc='')=>`<div class="section-head"><div><p class="eyebrow">${esc(kicker)}</p><h2>${esc(title)}</h2>${desc?`<p>${esc(desc)}</p>`:''}</div></div>`;
const catCard=(c)=>{const count=tools.filter(t=>t.category===c.slug).length;return `<a class="category-card" href="/categories/${attr(c.slug)}/"><span class="category-symbol" aria-hidden="true">${esc(c.symbol)}</span><span class="category-name">${esc(c.name)}</span><span class="category-meta">${count} curated tools <span aria-hidden="true">↗</span></span></a>`};
const counts={total:tools.length,verified:tools.filter(t=>t.verifiedOn).length,categories:categories.length};
const collectionSchema={'@context':'https://schema.org','@type':'CollectionPage',name:'FreeAITaskbook — Free AI tools for real tasks',url:canon('/'),description:'A task-focused AI tools directory with free tier notes, categories and direct links to official providers.'};
const home=`<div class="dark-hero"><div class="wrap hero"><div class="hero-content"><p class="hero-eyebrow"><span class="pulse"></span> The human-first directory of AI tools <span class="eye-star">✳</span></p><h1>Great ideas.<br/><em>Zero barriers.</em></h1><p class="hero-sub">Find the right free AI tool for what you're trying to do. Real use cases, clearer free limits, and zero guesswork.</p><form class="hero-search" action="/#explore" method="get"><label class="sr-only" for="hero-query">Search free AI tools</label><span class="search-ico" aria-hidden="true">⌕</span><input id="hero-query" name="q" type="search" autocomplete="off" placeholder="What do you want to do with AI?" maxlength="140"><button type="submit">Find my tool <span aria-hidden="true">↗</span></button></form><div class="intent-line"><span>Try:</span><a href="/?q=make%20a%20presentation#explore">make a presentation ↗</a><a href="/?q=code#explore">write code ↗</a><a href="/?q=transcription#explore">transcribe audio ↗</a></div><div class="hero-stats"><div><strong>${counts.total}+</strong><span>Starting tools</span></div><div><strong>${counts.categories}</strong><span>Areas to explore</span></div><div><strong>₹0</strong><span>To browse. Always.</span></div></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><div class="art-center"><span class="art-big">AI</span><span class="art-sub">FIND YOUR WAY</span></div><span class="floating-token tok-one">✺</span><span class="floating-token tok-two">◆</span><span class="floating-token tok-three">✳</span><span class="floating-token tok-four">✦</span><span class="art-scribble">DISCOVER<br/>WHAT'S POSSIBLE <b>↗</b></span></div></div><div class="wrap hero-overlap"><div class="trust-banner"><span class="trust-icon">✓</span><div><strong>Clearer than another list of links.</strong><span>Free plans, one-time credits and local software are labeled differently. Some entries are awaiting independent review.</span></div><a href="/about/">How we review <span aria-hidden="true">↗</span></a></div></div></div><div class="wrap main-content"><section class="section categories-section" aria-labelledby="category-heading"><div class="section-head split"><div><p class="eyebrow">✳ START WITH A GOAL</p><h2 id="category-heading">What are you <em>creating?</em></h2><p>Choose a category, or skip straight to the tools.</p></div><a href="/categories/" class="text-link">See all categories <span aria-hidden="true">↗</span></a></div><div class="category-grid">${categories.slice(0,6).map(catCard).join('')}</div><details class="progressive-panel"><summary>See more categories ↓</summary><div class="category-grid expanded-category-grid">${categories.slice(6).map(catCard).join('')}</div></details></section><section id="explore" class="section tools-section" aria-labelledby="tools-heading"><div class="section-head split"><div><p class="eyebrow">THE GOOD STUFF</p><h2 id="tools-heading">Meet your next <em>favorite tool.</em></h2><p>Search and filter ${counts.total} starter listings. No account needed.</p></div><span class="outlined-stamp">CURATED FOR HUMANS <span aria-hidden="true">✳</span></span></div><div class="explorer"><div class="filter-top"><label class="filter-search" for="tool-search"><span aria-hidden="true">⌕</span><input type="search" id="tool-search" placeholder="Search names, tasks or keywords..." maxlength="140" autocomplete="off"></label><label class="field-label" for="category-filter">Category <select id="category-filter"><option value="">All categories</option>${categories.map(c=>`<option value="${attr(c.slug)}">${esc(c.name)}</option>`).join('')}</select></label><label class="field-label" for="access-filter">Cost <select id="access-filter"><option value="">All free options</option>${Object.entries(accessLabels).map(([k,v])=>`<option value="${attr(k)}">${esc(v)}</option>`).join('')}</select></label></div><div class="filter-bottom"><span id="results-count" aria-live="polite">Showing ${tools.length} tools</span><div class="filter-actions"><button class="filter-toggle" id="favorites-toggle" type="button" aria-pressed="false">☆ Saved tools</button><button class="reset-filters" id="clear-filters" type="button">Reset filters ↺</button></div></div><div class="tools-grid" id="tools-grid">${[...tools].sort((a,b)=>Number(b.featured)-Number(a.featured)||a.name.localeCompare(b.name)).map(card).join('')}</div><div class="grid-pager"><button id="show-more-tools" type="button" class="show-more-button" aria-controls="tools-grid">Show 6 more tools ↓</button><a href="/search/">Search all resources ↗</a></div><div class="empty-state" id="no-results" hidden><span>⌕</span><h3>No exact match found.</h3><p>Try a different task, remove a filter, or explore another category.</p><button type="button" id="empty-reset">Clear filters</button></div></div></section><section class="section compact-paths"><div class="section-head"><p class="eyebrow">EXPLORE FURTHER</p><h2>Everything you need, <em>one click away.</em></h2></div><div class="path-links"><a href="/professions/">✳ Professional toolkits ↗</a><a href="/apis/">◇ Free &amp; paid APIs ↗</a><a href="/jobs/">⌁ Career sources ↗</a><a href="/learn/">▷ YouTube courses &amp; learning ↗</a></div></section><section class="end-cta"><span class="cta-ribbon">FOR THE BUILDERS, THINKERS & DOERS</span><div><h2>Know a tool we're <em>missing?</em></h2><p>Help people find more useful AI. Suggest a tool, report a changed free plan or contribute a better description.</p><a href="/submit/" class="btn-dark">Suggest an AI tool <span aria-hidden="true">↗</span></a></div><span class="big-asterisk" aria-hidden="true">✳</span></section></div>`;
save('index.html',page({title:'FreeAITaskbook',description:`Discover ${tools.length} free, freemium and local AI tools for writing, coding, design, research and more. Compare free access and find the right tool for your task.`,pathname:'/',content:home,ld:collectionSchema}));
const categoriesPage=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Categories'}])}<p class="eyebrow">EXPLORE BY INTENTION</p><h1>Every task has <em>a tool.</em></h1><p>Browse ${categories.length} practical categories of free-to-start and local AI software.</p></div></div><section class="wrap section"><div class="category-grid all-categories">${categories.map(catCard).join('')}</div><p class="editor-note">Every listing links to its provider's website. Some tool details are still awaiting independent pricing review.</p></section>`;
save('categories/index.html',page({title:'Free AI Tool Categories',description:`Browse ${categories.length} categories of free AI tools, from research and video to coding, data analysis and local models.`,pathname:'/categories/',content:categoriesPage}));
for(const c of categories){const list=tools.filter(t=>t.category===c.slug);const title=`Free AI Tools for ${c.name}`;const p=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Categories',url:'/categories/'},{name:c.name}])}<p class="eyebrow">${esc(c.symbol)} / ${list.length} TOOLS</p><h1>${esc(c.name)}<em>.</em></h1><p>${esc(c.description)}. Explore free plans, limited credits and options you can run locally.</p></div></div><section class="wrap section"><div class="section-head split"><div><p class="eyebrow">BROWSE YOUR OPTIONS</p><h2>Tools worth <em>exploring.</em></h2></div><a class="text-link" href="/?category=${attr(c.slug)}#explore">Search all tools ↗</a></div><div class="tools-grid">${list.map(card).join('')}</div><p class="editor-note">Information changes. Check each provider's current pricing, licences and regional availability before relying on the free option.</p></section>`;
 save(`categories/${c.slug}/index.html`,page({title,description:`Explore ${list.length} tools for ${c.name.toLowerCase()}. ${c.description}. See free plan caveats, pricing sources and official links.`,pathname:`/categories/${c.slug}/`,content:p,ld:{'@context':'https://schema.org','@type':'CollectionPage',name:title,url:canon(`/categories/${c.slug}/`)}}));}
for(const t of tools){const c=catMap[t.category];const affiliate=affiliates[t.slug];const dest=affiliate||t.url;const officialText=affiliate?'Visit tool (affiliate link)':'Visit official website';const label=affiliate?`<span class="affiliate-tag">Affiliate link · we may earn a commission</span>`:'';
 const similar=tools.filter(v=>v.slug!==t.slug && v.category===t.category).slice(0,3);
 const info=`<div class="page-hero detail-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:c.name,url:`/categories/${c.slug}/`},{name:t.name}])}<div class="detail-head"><span class="detail-monogram">${esc(t.name.slice(0,2).toUpperCase())}</span><div><p class="eyebrow">${esc(c.name.toUpperCase())} / TOOL SPOTLIGHT</p><h1>${esc(t.name)}<em>.</em></h1><p>${esc(t.summary)}</p></div></div><div class="detail-actions"><a class="btn-primary" href="${attr(dest)}" rel="noopener noreferrer${affiliate?' sponsored nofollow':''}" target="_blank">${officialText} <span aria-hidden="true">↗</span></a><a href="${attr(t.pricingUrl)}" class="btn-outline" target="_blank" rel="noopener noreferrer">Official pricing / documentation ↗</a></div>${label}</div></div><section class="wrap detail-layout section"><div class="detail-main"><p class="eyebrow">AT A GLANCE</p><h2>What can you do with <em>${esc(t.name)}?</em></h2><p>${esc(t.description)}</p><h3>Common use cases</h3><div class="chip-row">${t.tasks.map(x=>`<span class="task-chip">${esc(x)}</span>`).join('')}</div><h3>What is available for free?</h3><p>${esc(t.freeNote)}</p><div class="notice"><strong>Important:</strong> Free access does not necessarily include business use, unlimited generations or paid API access. Always verify current terms with the provider before committing work or money.</div><h3>Where to verify the details</h3><p>We link directly to the provider's official documentation so you can confirm free allowances, account requirements and usage rights.</p><a class="text-link" href="${attr(t.pricingUrl)}" rel="noopener noreferrer" target="_blank">View provider documentation ↗</a></div><aside class="detail-sidebar"><div class="info-panel"><p class="eyebrow">FREE ACCESS SNAPSHOT</p><div>${tag(t)}</div><dl><dt>Category</dt><dd><a href="/categories/${attr(c.slug)}/">${esc(c.name)}</a></dd><dt>Listing review</dt><dd>${t.verifiedOn?`Official source checked ${esc(t.verifiedOn)}`:'Independent review pending'}</dd><dt>Official website</dt><dd><a href="${attr(t.url)}" rel="noopener noreferrer" target="_blank">${esc(new URL(t.url).hostname)} ↗</a></dd></dl><div class="disclaimer-small">We do not guarantee provider availability or free allowances. ${affiliate?'This page uses an affiliate link.':'This entry currently uses a non-affiliate official link.'}</div></div></aside></section>${similar.length?`<section class="wrap section related-section">${sectionHead('KEEP EXPLORING','More in '+c.name)}<div class="tools-grid related-grid">${similar.map(card).join('')}</div></section>`:''}`;
 const structured={'@context':'https://schema.org','@type':'WebPage',name:`${t.name}: Free AI Tool & Pricing Notes`,url:canon(`/tools/${t.slug}/`),description:t.summary,mainEntity:{'@type':'SoftwareApplication',name:t.name,url:t.url,applicationCategory:c.name,description:t.description}};
 save(`tools/${t.slug}/index.html`,page({title:`${t.name}: Free Plan, Uses & Alternatives`,description:`${t.name}: ${t.summary} Find the free-access type, important limitations and official source in FreeAITaskbook.`,pathname:`/tools/${t.slug}/`,content:info,ld:structured}));}
const guideData=[
 {slug:'how-to-find-actually-free-ai-tools',title:'How to find AI tools that are actually free',dek:'A quick framework for checking free plans, credits, trials and real usage rights.',paras:[['The four labels that matter','A permanent free plan may renew each month, while one-time credits eventually run out. Open-source software can be free to install but require a capable laptop or paid hosting. A limited trial is not the same as an ongoing free plan.'],['Check the official pricing page','Before choosing a tool, find the vendor’s current pricing or plan page. Look for a $0 plan, quota renewal rules, required payment cards, watermarks, export restrictions and business-use permissions.'],['Test with a real task','Try a small version of your intended workflow. A free tool is useful only if you can complete the task and export a result under the current limits.'],['Recheck before production','Providers change plans frequently. Confirm licensing, usage rights and pricing again before using a tool in client work or in a commercial product.']]},
 {slug:'free-ai-stack-for-students-and-creators',title:'A practical free AI toolkit for students and creators',dek:'Organize a useful workflow without buying several subscriptions on day one.',paras:[['Research and questions','Use an assistant for brainstorming and a source-focused research tool for verifying claims. Review original sources before submitting assignments or publishing content.'],['Writing and study notes','Turn your source materials into outlines, flashcards and drafts. Review any AI-generated summary against the original material.'],['Visuals and slides','Combine free design tools with a presentation editor. Watch for premium media assets, export watermarks and commercial licence restrictions.'],['Video and voice','Free quotas can be tight, particularly for generative video and high-quality audio. Start with short samples and check how free credits reset.'],['Stay organized','Bookmark tools you find useful and avoid uploading confidential or sensitive documents to services without reviewing their policies.']]}
];
const guidesIndex=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Guides'}])}<p class="eyebrow">HELPFUL, NOT HYPED</p><h1>A little more <em>clarity.</em></h1><p>Practical, independent guides to making better AI choices.</p></div></div><section class="wrap section"><div class="guide-grid">${guideData.map((g,i)=>`<a class="guide-card" href="/guides/${g.slug}/"><span class="eyebrow">GUIDE / 0${i+1}</span><h2>${esc(g.title)}</h2><p>${esc(g.dek)}</p><span>Read the guide ↗</span></a>`).join('')}</div></section>`;
save('guides/index.html',page({title:'Free AI Guides',description:'Helpful guides on comparing free AI plans and putting together an effective no-cost AI toolkit.',pathname:'/guides/',content:guidesIndex}));
for(const g of guideData){const body=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Guides',url:'/guides/'},{name:g.title}])}<p class="eyebrow">A PRACTICAL FREE AI GUIDE</p><h1>${esc(g.title)}<em>.</em></h1><p>${esc(g.dek)}</p></div></div><article class="wrap article section">${g.paras.map(([h,p])=>`<h2>${esc(h)}</h2><p>${esc(p)}</p>`).join('')}<p>Ready to compare options? <a href="/#explore">Explore the directory ↗</a></p></article>`;save(`guides/${g.slug}/index.html`,page({title:g.title,description:g.dek,pathname:`/guides/${g.slug}/`,content:body,ld:{'@context':'https://schema.org','@type':'Article',headline:g.title,datePublished:TODAY,author:{'@type':'Organization',name:'FreeAITaskbook'}}}));}
function simple(slug,title,headline,body,desc){save(`${slug}/index.html`,page({title,description:desc||title,pathname:`/${slug}/`,content:`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:title}])}<p class="eyebrow">FREEAITASKBOOK</p><h1>${headline}</h1></div></div><article class="wrap article section">${body}</article>`}));}
simple('about','About & Review Policy','A directory built for <em>real people.</em>',`<h2>Our mission</h2><p>FreeAITaskbook helps people discover useful AI software by task, with direct links and clear language about what free actually means.</p><h2>How we classify access</h2><p><strong>Fully free</strong> means the provider offers free use for the core experience. <strong>Free plan</strong> means recurring no-cost access with restrictions. <strong>Limited free credits</strong> means the free allocation may not replenish. <strong>Local / open source</strong> means software or model workflows can run locally, potentially requiring your own hardware. <strong>Free software</strong> covers other no-cost applications with important license or hosting caveats.</p><h2>Review policy</h2><p>Only listings with a review date claim a checked official provider source. All other starter listings are labeled as awaiting independent review. We do not copy ratings or invent free quotas. Submit corrections with an official pricing or documentation link.</p><h2>Editorial independence</h2><p>Future affiliate partnerships and sponsored content will be disclosed. We do not present paid placements as unbiased rankings. Listings may be removed if their free access or product existence cannot be substantiated.</p><h2>How to contribute</h2><p>Use our <a href="/submit/">submission instructions</a>. The repository stores structured JSON data so community members can propose changes and reviewers can audit their sources.</p>`,'Learn how FreeAITaskbook researches free AI tools, distinguishes free plans from credits, and welcomes community corrections.');
simple('submit','Submit an AI Tool or API','Help the directory <em>grow.</em>',`<h2>Suggest a new tool or API</h2><p>Fill in the details below. Clicking the button prepares a <strong>public GitHub issue</strong>; you must sign in to GitHub and press Submit there. Your suggestion receives an automatic acknowledgement. Listings are published <strong>only after a maintainer reviews and approves them</strong>.</p><p><strong>Privacy:</strong> GitHub issues are public. Do not include email addresses, personal data, passwords, private API keys or confidential documents.</p><form class="suggest-form" id="suggest-form" data-repo="${attr(REPO)}"><label>Listing type<select name="kind" required><option value="Tool">AI tool (free or free-to-start)</option><option value="API">API / integration (free or paid)</option></select></label><label>Tool / API name<input name="name" required maxlength="80" placeholder="e.g. A useful tool"></label><label>Official website<input name="website" type="url" required pattern="https://.*" placeholder="https://provider.example"></label><label>Official pricing or documentation URL<input name="pricing" type="url" required pattern="https://.*" placeholder="https://provider.example/pricing"></label><label>Category<select name="category" required><option value="chat-research">Chat & research</option><option value="coding">Coding</option><option value="design">Design</option><option value="video">Video</option><option value="audio">Audio</option><option value="writing">Writing</option><option value="presentations">Presentations</option><option value="productivity">Productivity</option><option value="automation">Automation</option><option value="data">Data</option><option value="local">Local / open source</option><option value="website">Websites</option><option value="AI">API: AI models</option><option value="Commerce">API: Commerce</option><option value="Websites">API: Websites</option><option value="Email">API: Email</option><option value="Maps">API: Maps</option><option value="Database">API: Database</option><option value="Payments">API: Payments</option><option value="Media">API: Media</option><option value="Developer">API: Developer</option></select></label><label>Access<select name="access" required><option value="free-tier">Recurring free tier</option><option value="free">Fully free</option><option value="free-credits">Limited / trial credits</option><option value="local-open-source">Local / open source</option><option value="free-software">Free software</option><option value="paid">Paid API</option><option value="platform-included">Included with a platform/store</option><option value="self-hosted">Self-hosted</option></select></label><label>What does it help with?<textarea name="description" required rows="3" maxlength="800" placeholder="Describe concrete use cases and tasks"></textarea></label><label>Limits / requirements<textarea name="limitations" required rows="3" maxlength="800" placeholder="Free limits, paid pricing, required account, or key setup"></textarea></label><label>Integration approach (for APIs)<select name="platforms"><option value="custom,wordpress,shopify">Custom, WordPress and Shopify (via integration)</option><option value="custom">Custom apps only</option><option value="wordpress,custom">WordPress and custom apps</option><option value="shopify,custom">Shopify and custom apps</option></select></label><button class="btn-dark" type="submit">Continue to GitHub submission ↗</button><p id="submission-help" role="status">No information is sent from this page until you submit your issue on GitHub.</p></form><p>Alternatively, use the <a href="${attr(REPO)}/issues/new/choose" target="_blank" rel="noopener noreferrer">GitHub issue templates</a>. You can also submit a pull request directly.</p>`,'Suggest an AI tool or API for human-reviewed publication through a GitHub issue.');
simple('disclosure','Affiliate Disclosure','Clear links. <em>Clear incentives.</em>',`<h2>Affiliate relationships</h2><p>Some outbound links on FreeAITaskbook may become affiliate links. If you click one and make a qualifying purchase, the project may receive a commission at no additional cost to you. Affiliate links are labeled where used.</p><p><strong>At initial launch, the affiliate configuration contains no active affiliate URLs.</strong> Adding one requires approval from the relevant vendor or affiliate network.</p><h2>Sponsored content</h2><p>If we later accept sponsored placements, they will be distinctly identified. Payment does not guarantee a favorable review or override our free-plan classification criteria.</p><h2>Accuracy</h2><p>Pricing, features and terms change. Always confirm with the provider. A link to a product is not an endorsement or guarantee of eligibility.</p>`,'Learn how FreeAITaskbook discloses affiliate links and potential future sponsorships.');
simple('privacy','Privacy Policy','Privacy in <em>plain language.</em>',`<h2>Public browsing</h2><p>You can browse FreeAITaskbook without creating an account. Search and filters work in your browser; saved bookmarks are stored in your browser using localStorage. We do not install an advertising or analytics tracker in this version.</p><h2>Community submissions</h2><p>The submit form constructs an issue draft and opens GitHub. Content submitted there is public and is subject to GitHub's privacy practices. Never post personal data, private keys, or sensitive business information in an issue.</p><h2>Optional account sign-in</h2><p>If enabled by the operator, account sign-in uses Supabase Auth via an email link. The email address is processed by Supabase for identity, account management, and security. Account emails are visible to the site's authorized Supabase administrator. We do not need your personal password. Creating an account is optional and does not subscribe you to marketing messages.</p><h2>Choices and requests</h2><p>Users may browse without an account. If optional accounts become enabled, requests for account deletion or data access should be sent to the published privacy contact: ${PRIVACY_CONTACT_EMAIL?`<a href="mailto:${attr(PRIVACY_CONTACT_EMAIL)}">${esc(PRIVACY_CONTACT_EMAIL)}</a>`:'the site operator, once an account-support contact is configured'}.</p><h2>Hosting and third parties</h2><p>Cloudflare may process normal hosting logs; GitHub and linked tool providers have separate practices. Provider services and free tiers change. We do not sell private API keys or user credentials.</p><h2>Legal review</h2><p>This privacy notice should be reviewed and expanded as features, third-party vendors, retention policies, or the business model change.</p>`,'How FreeAITaskbook handles browsing, optional sign-in, community submissions, and external providers.');
simple('terms','Terms of Use','Use responsibly. <em>Build freely.</em>',`<h2>Informational directory</h2><p>FreeAITaskbook is an independent information directory. It is not affiliated with the listed tool providers unless explicitly stated. All vendor names and marks remain with their respective owners.</p><h2>No warranty</h2><p>Listings and free-tier descriptions are provided for general information without guarantees of accuracy, availability, fitness for purpose or commercial-use rights. Check providers' official terms before using a tool.</p><h2>Community contributions</h2><p>Do not submit personal data, private keys, copyrighted content you cannot share, or malicious links. Contributors should provide original descriptions and official source links. Contributions to source code are governed by the repository's published licence.</p><h2>Legal review</h2><p>This starter text should be reviewed for your jurisdiction and business before launching paid services or advertising.</p>`,'Terms of use for this open, informational free AI tools directory.');

// API & integration catalog: credentials are always created by each visitor at the provider.
const apiLabels={'free-tier':'Free tier','free-credits':'Free credits','paid':'Usage-based / paid','platform-included':'Platform required','self-hosted':'Self-hosted'};
const apiCategories=[...new Set(apis.map(a=>a.category))];
const apiCard=(a)=>`<article class="api-card" data-api data-search="${attr([a.name,a.category,a.description,...a.platforms].join(' ').toLowerCase())}" data-access="${attr(a.access)}" data-platforms="${attr(a.platforms.join(','))}"><span class="api-kicker">${esc(a.category)} · ${esc(apiLabels[a.access])}</span><h2><a href="/apis/${attr(a.slug)}/">${esc(a.name)} ↗</a></h2><p>${esc(a.description)}</p><div class="api-meta">${a.platforms.map(p=>`<span>${esc(p)}</span>`).join('')}</div></article>`;
const apiIndex=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'API & Integration Directory'}])}<p class="eyebrow">PUBLIC API DISCOVERY</p><h1>APIs for <em>every build.</em></h1><p>Discover free-tier, platform-included and paid APIs for AI, Shopify, WordPress and custom apps. We show where to get your own key, never shared private credentials.</p></div></div><section class="wrap section api-directory"><h2>Explore ${apis.length} API providers</h2><div class="api-filters"><label>Find an API<input id="api-search" type="search" placeholder="AI, maps, Shopify, email..."></label><label>Access<select id="api-access"><option value="">All access types</option>${Object.entries(apiLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Use case<select id="api-platform"><option value="">All platforms</option><option value="shopify">Shopify</option><option value="wordpress">WordPress</option><option value="custom">Custom apps</option></select></label></div><p id="api-count" role="status"></p><div class="api-grid">${apis.map(apiCard).join('')}</div><p id="api-none" hidden>No matching APIs. Try a different search.</p><div class="notice">A public API directory provides documentation and eligibility details, not other users' credentials. Charges, authorization and quotas vary by provider.</div></section>`;
save('apis/index.html',page({title:'Free and Paid APIs for AI, Shopify, WordPress & Custom Apps',description:'Find and compare free API tiers, paid APIs, and documentation for AI, Shopify, WordPress, and custom apps.',pathname:'/apis/',content:apiIndex,ld:{'@context':'https://schema.org','@type':'CollectionPage',name:'API and Integration Directory',url:canon('/apis/')}}));
for(const a of apis){const plat=a.platforms.map(s=>`<span class="task-chip">${esc(s)}</span>`).join('');const body=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'APIs',url:'/apis/'},{name:a.name}])}<p class="eyebrow">${esc(a.category)} · ${esc(apiLabels[a.access])}</p><h1>${esc(a.name)}</h1><p>${esc(a.description)}</p></div></div><article class="wrap article section"><h2>How to obtain API access</h2><p>${esc(a.keyInstructions)}</p><p><strong>Never share account credentials or private API keys.</strong> Public example values are not reusable credentials.</p><h2>Pricing, quotas and limitations</h2><p>${esc(a.limitations)}</p><p>${a.verifiedOn?`Official documentation reviewed on ${esc(a.verifiedOn)}; terms can change without notice.`:'Independent free-tier verification pending. Check the provider before purchase or integration.'}</p><h2>Integration use cases</h2><div class="chip-row">${plat}</div><p>Platform tags represent possible integration paths, not guaranteed native plugins or merchant authorization.</p><p><a class="btn-dark" href="${attr(a.keyUrl)}" target="_blank" rel="noopener noreferrer">Get your own API key / access ↗</a></p><p><a href="${attr(a.docsUrl)}" target="_blank" rel="noopener noreferrer">Official API documentation ↗</a></p><p><a href="${attr(a.pricingUrl)}" target="_blank" rel="noopener noreferrer">Official pricing / access terms ↗</a></p><p><a href="/submit/">Suggest an update or another API ↗</a></p></article>`;
 save(`apis/${a.slug}/index.html`,page({title:a.name+' API: Pricing, Free Tier and Key Setup',description:a.description+' Learn the access requirements and where to get your own key.',pathname:`/apis/${a.slug}/`,content:body,ld:{'@context':'https://schema.org','@type':'SoftwareApplication',name:a.name,description:a.description,applicationCategory:a.category,url:a.docsUrl}}));}
// Account page stays closed until a Supabase project and privacy contact are configured.
const accountBody=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Account'}])}<p class="eyebrow">OPTIONAL ACCOUNT ACCESS</p><h1>Find tools <em>your way.</em></h1><p>The directory remains free without an account. Account sign-in, when configured, uses an email magic link — we never ask for a password.</p></div></div><article class="wrap article section"><h2>Account</h2><div class="auth-panel" id="auth-panel" data-auth-url="${attr(AUTH_ENABLED?AUTH_URL:'')}" data-auth-key="${attr(AUTH_ENABLED?AUTH_PUBLISHABLE_KEY:'')}">${AUTH_ENABLED?`<form id="auth-form"><label>Your email address<input id="auth-email" type="email" required autocomplete="email" maxlength="254" placeholder="you@example.com"></label><label class="check-row"><input type="checkbox" id="auth-consent" required> I agree to the <a href="/privacy/">privacy notice</a> and understand my email will be stored with our authentication provider.</label><button class="btn-dark" type="submit">Email me a sign-in link ↗</button></form><div id="auth-profile" hidden><p>Signed in as <strong id="auth-user-email"></strong>.</p><button type="button" class="btn-dark" id="auth-signout">Sign out</button></div><p role="status" id="auth-message"></p>`:`<div class="notice"><strong>Account sign-in is not enabled yet.</strong> You can browse all listings without an account. The site owner must configure Supabase Auth and a privacy contact before account collection can begin.</div>`}</div><h2>What do we collect?</h2><p>When activated, only your email address and account sign-in metadata are needed initially. No website-specific password, hidden lead capture, or marketing opt-in is required. See <a href="/privacy/">Privacy Policy</a>.</p></article>`;
save('account/index.html',page({title:'Account Login',description:'Optional email-link sign-in for FreeAITaskbook, once secure account services are enabled.',pathname:'/account/',content:accountBody,noindex:!AUTH_ENABLED}));
save('404.html',page({title:'Page not found',description:'The requested page could not be found.',pathname:'/404/',content:`<div class="wrap not-found"><span>404 / LOST IN THE MULTIVERSE</span><h1>Not all paths<br/>lead to <em>AI.</em></h1><p>This page moved or never existed. Find something useful instead.</p><a class="btn-dark inline-btn" href="/">Back to all tools ↗</a></div>`,noindex:true}));

// New additive navigation pages: real provider/source URLs; no fabricated jobs, quotas, or certificates.
const indexHero=(title,subtitle,links)=>`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:title}])}<p class="eyebrow">FREEAITASKBOOK · EXPLORE</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div></div><section class="wrap section"><div class="guide-grid">${links.map(l=>`<a class="guide-card" href="${attr(l.url)}"><span class="eyebrow">${esc(l.type||'RESOURCE')}</span><h2>${esc(l.name)}</h2><p>${esc(l.description)}</p><span>Explore ↗</span></a>`).join('')}</div></section>`;
const professionLinks=professions.map(x=>({name:x.name,description:x.description,url:`/professions/${x.slug}/`,type:'PROFESSION'}));
save('professions/index.html',page({title:'AI Toolkits by Profession',description:'Free AI workflows and verified tool links for business analysts, designers, website creators and app developers.',pathname:'/professions/',content:indexHero('Professional AI Toolkits','Discover practical AI workflows by profession and compare relevant tools.',professionLinks)}));
for(const prof of professions){
 const steps=prof.workflows.map(w=>`<section class="info-panel"><h2>${esc(w.goal)}</h2><p>${esc(w.example)}</p><div class="chip-row">${w.tools.map(slug=>{const t=tools.find(x=>x.slug===slug);return t?`<a class="task-chip" href="/tools/${attr(slug)}/">${esc(t.name)} ↗</a>`:''}).join('')}</div></section>`).join('');
 const body=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Professions',url:'/professions/'},{name:prof.name}])}<h1>${esc(prof.name)}</h1><p>${esc(prof.description)}</p></div></div><section class="wrap section"><p class="editor-note">These are workflow examples, not endorsements or guarantees of a permanent free plan. Check provider quotas before use.</p><div class="guide-grid">${steps}</div></section>`;
 save(`professions/${prof.slug}/index.html`,page({title:prof.name,description:prof.description,pathname:`/professions/${prof.slug}/`,content:body}));
}
const sourceCard=x=>`<article class="guide-card" data-job-source data-search="${attr([x.name,x.type,x.region,x.description].join(' ').toLowerCase())}"><span class="eyebrow">${esc(x.type.toUpperCase())} · ${esc(x.region)}</span><h2>${esc(x.name)}</h2><p>${esc(x.description)}</p><a href="${attr(x.url)}" rel="noopener noreferrer" target="_blank">Visit official website ↗</a></article>`;
const jobLanding=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Jobs'}])}<p class="eyebrow">JOB SOURCE DIRECTORY</p><h1>Explore career opportunities <em>at the source.</em></h1><p>Browse ${jobSources.length} recruitment portals. Verified vacancies appear below when an authorized data source is configured. Always confirm eligibility and deadlines from official notices.</p></div></div><section class="wrap section"><h2>Verified current vacancies</h2><p class="editor-note">Vacancies appear here only after source attribution and administrator verification. No listings are invented or treated as current by default.</p><div id="verified-job-feed" data-api-url="${attr(AUTH_ENABLED?AUTH_URL:'')}" data-api-key="${attr(AUTH_ENABLED?AUTH_PUBLISHABLE_KEY:'')}"><p id="verified-job-status" role="status">${AUTH_ENABLED?'Checking verified vacancies…':'Verified vacancy feed is not configured yet. Use the recruitment portals below.'}</p><div class="guide-grid" id="verified-job-cards"></div></div></section><section class="wrap section"><h2>Recruitment portal directory</h2><label class="filter-search" for="source-search"><span aria-hidden="true">⌕</span><input id="source-search" type="search" placeholder="Search government, remote, Kolkata, internships or portal names" autocomplete="off"></label><p role="status" id="source-results">${jobSources.length} job sources</p><div class="guide-grid" id="source-grid">${jobSources.map(sourceCard).join('')}</div><p class="editor-note">Aggregators may summarize employer advertisements; official recruiting organizations remain authoritative. These are directory links, not current vacancy claims.</p></section>`;
save('jobs/index.html',page({title:'Government, Private & Remote Job Source Directory',description:'Browse verified website links for official government recruitment, private jobs, internships, Kolkata careers and remote work.',pathname:'/jobs/',content:jobLanding}));
save('jobs/sources/index.html',page({title:'Job Source Websites',description:'Official government portals, private job boards and remote/internship recruitment websites in one directory.',pathname:'/jobs/sources/',content:jobLanding}));
const accessNames={'free-learning':'Free learning · certificate not assured','free-certificate-conditional':'Free certificate · subject to completion rules','provider-review':'Provider resources · check access and fees'};
const courseCards=learning.map(l=>`<article class="guide-card"><span class="eyebrow">${esc(l.topic.toUpperCase())}</span><h2>${esc(l.provider)}</h2><p>${esc(accessNames[l.access])}</p><p>${esc(l.note)}</p><a href="${attr(l.url)}" target="_blank" rel="noopener noreferrer">Visit course provider ↗</a></article>`).join('');

const videoTopics=[...new Set(youtubeCourses.map(c=>c.topic))];
const topicOptions=videoTopics.map(t=>'<option value="'+attr(t)+'">'+esc(t)+'</option>').join('');
const videoCards=youtubeCourses.map(c=>'<article class="video-course-card" data-video-course data-topic="'+attr(c.topic)+'"><div class="video-cover"><span aria-hidden="true">▶</span><small>FREE ON YOUTUBE</small></div><div class="video-info"><p class="video-kicker">'+esc(c.topic)+' · '+esc(c.level)+'</p><h3>'+esc(c.title)+'</h3><p class="video-channel">'+esc(c.channel)+'</p><p class="video-description">'+esc(c.description)+'</p><button type="button" class="video-watch" data-video-id="'+attr(c.id)+'" data-video-title="'+attr(c.title)+'">Watch here ↗</button><a href="https://www.youtube.com/watch?v='+attr(c.id)+'" target="_blank" rel="noopener noreferrer">Open on YouTube ↗</a></div></article>').join('');
const videoSection='<section class="wrap section learning-section"><div class="section-head split"><div><p class="eyebrow">CURATED YOUTUBE COURSES</p><h2>Watch, practice, <em>grow.</em></h2><p>Free videos for practical skills, chosen from identifiable publishers.</p></div></div><label class="video-filter-label" for="video-topic">Topic <select id="video-topic"><option value="">All topics</option>'+topicOptions+'</select></label><div class="video-course-grid" id="video-course-grid">'+videoCards+'</div><div id="video-player" class="video-player" hidden><div class="video-player-head"><strong id="video-player-title">Video lesson</strong><button type="button" id="video-player-close">Close video ×</button></div><div id="video-frame-slot"></div></div><p class="editor-note">These courses are independently published. YouTube loads only after clicking Watch. Free viewing does not guarantee a certificate.</p></section>';

const learnBody=`<div class="page-hero"><div class="wrap">${breadcrumb([{name:'Home',url:'/'},{name:'Learn'}])}<p class="eyebrow">LEARN AND PRACTICE</p><h1>Free learning, <em>clearly labeled.</em></h1><p>Find useful training for Business Analysis, SQL, data, programming, website building and more. Certification terms vary by provider.</p></div></div><section class="wrap section"><div class="guide-grid">${courseCards}</div><p class="editor-note">Course and certificate eligibility can change. Read current provider requirements before enrollment.</p></section>`;
save('learn/index.html',page({title:'Free Learning and Certifications Directory',description:'Free learning resources for SQL, Power BI, Business Analysis, Python, GitHub, Cloudflare, Agile and web development.',pathname:'/learn/',content:learnBody.replace('<div class="guide-grid">',videoSection+'<details class="progressive-panel"><summary>Other learning resources ↓</summary><div class="guide-grid learning-resource-grid">').replace('</div><p class="editor-note">Course and certificate eligibility','</div></details><p class="editor-note">Course and certificate eligibility')} ).replace('</head>','<script defer src="/assets/learning.js"></script></head>'));

const pages=['/','/search/','/resources/','/professions/',...professions.map(x=>`/professions/${x.slug}/`),'/jobs/','/jobs/sources/','/learn/','/categories/','/guides/','/about/','/submit/','/apis/','/disclosure/','/privacy/','/terms/',...categories.map(c=>`/categories/${c.slug}/`),...tools.map(t=>`/tools/${t.slug}/`),...apis.map(a=>`/apis/${a.slug}/`),...guideData.map(g=>`/guides/${g.slug}/`)];
save('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.map(p=>`<url><loc>${esc(canon(p))}</loc></url>`).join('')}</urlset>`);
