const adminBody=`<div class="page-hero"><div class="wrap"><h1>Resource moderation</h1><p>Restricted access. Supabase app_metadata administrator role required; no self-registration for admins.</p></div></div><section class="wrap section" data-platform="admin"><p id="platform-status" role="status">Checking authorization…</p><div id="admin-private" hidden><h2>Pending suggestions</h2><div id="moderation-queue" class="guide-grid"></div><h2>Job-feed sync health</h2><p>Recent authorized-source runs, including failures. No results means no configured or executed feeds.</p><div id="sync-monitor" class="guide-grid"></div><h2>Publish verified resource</h2><p>Check official evidence before publishing. Only reviewed resources appear to visitors.</p><form id="admin-resource-form" class="suggest-form"><label>Type<select name="kind"><option value="ai_tool">AI tool</option><option value="api">API</option><option value="design">Design</option><option value="developer">Developer</option><option value="learning">Learning</option><option value="job_portal">Job portal</option></select></label><label>Name<input name="title" required minlength="2" maxlength="180"></label><label>Unique slug<input name="slug" required placeholder="example-tool"></label><label>Category<input name="category" required></label><label>Summary<textarea name="summary" required></textarea></label><label>Official URL<input name="official_url" type="url" required></label><label>Verification source URL<input name="source_url" type="url" required></label><label>Pricing status<select name="pricing_class"><option value="unverified">Unverified</option><option value="free">Fully free</option><option value="free_tier">Free tier</option><option value="free_credits">Credits</option><option value="open_source">Open source</option><option value="paid">Paid</option><option value="platform_included">Platform-included</option></select></label><button type="submit" class="btn-dark">Publish verified resource</button></form><h2>Publish verified vacancy</h2><form id="admin-job-form" class="suggest-form"><label>Source identifier<input name="source_key" required placeholder="employer-board"></label><label>Official external job ID<input name="external_id" required></label><label>Job title<input name="title" required></label><label>Organization<input name="organization" required></label><label>Location<input name="location"></label><label>Type<select name="job_type"><option value="private">Private</option><option value="government">Government</option><option value="internship">Internship</option><option value="remote">Remote</option><option value="other">Other</option></select></label><label>Official announcement URL<input name="official_notification_url" required type="url"></label><label>Application URL<input name="application_url" type="url"></label><label>Application deadline<input name="application_deadline" type="date"></label><button type="submit" class="btn-dark">Publish verified job</button></form></div></section>`;
